define('taoQtiItem/qtiCreator/widgets/static/helpers/verticalWritingEditing',['i18n', 'jquery', 'taoQtiItem/qtiCreator/helper/languages', 'taoQtiItem/qtiCommonRenderer/helpers/verticalWriting'], function (__, $, languages, verticalWriting) {
  'use strict';

  return {
    checkItemWritingMode: function checkItemWritingMode(widget) {
      var rootElement = widget.element.getRootElement();
      var itemLang = rootElement.attr('xml:lang');
      return languages.getVerticalWritingModeByLang(itemLang).then(supportedVerticalMode => {
        return {
          isVerticalSupported: supportedVerticalMode === 'vertical-rl',
          isItemVertical: !!rootElement.hasClass(verticalWriting.WRITING_MODE_VERTICAL_RL_CLASS)
        };
      });
    }
  };
});
