define('taoQtiItem/qtiCreator/widgets/choices/simpleAssociableChoice/Widget',['jquery', 'taoQtiItem/qtiCreator/widgets/choices/Widget', 'taoQtiItem/qtiCreator/widgets/choices/simpleAssociableChoice/states/states'], function ($, Widget, states) {
  var SimpleAssociableChoiceWidget = Widget.clone();
  SimpleAssociableChoiceWidget.initCreator = function () {
    this.registerStates(states);
    Widget.initCreator.call(this);
    this.$container.wrapInner($('<div>', {
      'class': 'inner-wrapper'
    }));
    this.$container.closest('table.matrix').find('input[type=checkbox]:enabled').prop('disabled', 'disabled');
  };
  return SimpleAssociableChoiceWidget;
});
