define('taoQtiItem/qtiCreator/model/Figure',['lodash', 'context', 'taoQtiItem/qtiCreator/model/mixin/editable', 'taoQtiItem/qtiItem/core/Figure', 'taoQtiItem/qtiCreator/model/Img', 'taoQtiItem/qtiCreator/model/Figcaption'], function (_, context, editable, Figure, Img, Figcaption) {
  'use strict';

  var DISABLE_FIGURE_WIDGET = context.featureFlags && context.featureFlags.FEATURE_FLAG_DISABLE_FIGURE_WIDGET;
  var methods = {};
  _.extend(methods, editable);
  _.extend(methods, {
    getDefaultAttributes() {
      return {
        showFigure: DISABLE_FIGURE_WIDGET || false
      };
    },
    afterCreate() {
      this.getNamespace();
      var img = new Img();
      this.setElement(img);
      if (this.getRenderer()) {
        img.setRenderer(this.getRenderer());
      }
    },
    addCaption(text) {
      var figcaption = _.find(this.getBody().elements, elem => elem.is('figcaption'));
      if (!figcaption) {
        figcaption = new Figcaption();
        figcaption.body(text);
        this.setElement(figcaption);
        var renderer = this.getRenderer();
        if (renderer) {
          figcaption.setRenderer(renderer);
          renderer.load(() => {}, ['figcaption']);
        }
      } else {
        figcaption.body(text);
      }
      return figcaption;
    },
    removeCaption() {
      var figcaption = _.find(this.getBody().elements, elem => elem.is('figcaption'));
      if (figcaption) {
        this.removeElement(figcaption);
      }
    }
  });
  return Figure.extend(methods);
});
